insert='''const circuitData:Record<string,[string,number,number]>={Australia:['Albert Park',-37.8497,144.968],China:['Shanghai International Circuit',31.3389,121.22],Japan:['Suzuka',34.843,136.54],Bahrain:['Bahrain International Circuit',26.0325,50.51],'Saudi Arabia':['Jeddah Corniche Circuit',21.6319,39.1044],Miami:['Miami International Autodrome',25.958, -80.239],'Emilia Romagna':['Imola',44.3439,11.7167],Monaco:['Circuit de Monaco',43.7347,7.4206],Spain:['Barcelona-Catalunya',41.57,2.261],Barcelona:['Barcelona-Catalunya',41.57,2.261],Canada:['Gilles Villeneuve',45.5,-73.522],Austria:['Red Bull Ring',47.2197,14.7647],'Great Britain':['Silverstone',52.0786,-1.0169],Belgium:['Spa-Francorchamps',50.4372,5.9714],Hungary:['Hungaroring',47.5789,19.2486],Netherlands:['Zandvoort',52.3888,4.5409],Italy:['Monza',45.6156,9.2811],Madrid:['Madring',40.466,-3.616],Azerbaijan:['Baku City Circuit',40.3725,49.8533],Singapore:['Marina Bay',1.2914,103.864],'United States':['Circuit of the Americas',30.1328,-97.6411],Mexico:['Hermanos Rodríguez',19.4042,-99.0907],Brazil:['Interlagos',-23.7036,-46.6997],'Las Vegas':['Las Vegas Strip Circuit',36.1147,-115.173],Qatar:['Lusail',25.49,51.4542],'Abu Dhabi':['Yas Marina',24.4672,54.6031]};
function Circuit({gp}:{gp:string}){const c=circuitData[gp];const [paths,P]=useState<string[]>([]);const [status,S]=useState('');const [busy,B]=useState(false);if(!c)return null;async function load(){B(true);S('');try{const query=`[out:json][timeout:20];way[highway=raceway](around:3000,${c[1]},${c[2]});out geom;`;const res=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:new URLSearchParams({data:query})});if(!res.ok)throw Error();const data=await res.json();const ways=(data.elements||[]).filter((w:any)=>Array.isArray(w.geometry)&&w.geometry.length>1).map((w:any)=>w.geometry.map((v:any)=>[v.lon*Math.cos(c[1]*Math.PI/180),-v.lat]));const all=ways.flat();if(!all.length)throw Error();const xs=all.map((v:number[])=>v[0]),ys=all.map((v:number[])=>v[1]);const x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y,k=Math.min(320/(w||1),160/(h||1));P(ways.map((a:number[][])=>a.map((v,i)=>`${i?'L':'M'}${(20+(320-w*k)/2+(v[0]-x)*k).toFixed(2)} ${(20+(160-h*k)/2+(v[1]-y)*k).toFixed(2)}`).join(' ')));S('OSM 주변 레이스웨이 · 피트레인 및 대체 코스 포함 가능 · 게임 레이아웃 미검증')}catch{S('지도 데이터를 불러오지 못했습니다. 잠시 후 다시 시도하세요.')}finally{B(false)}}return <section className="circuit"><div className="eyebrow">CIRCUIT EXPLORER / BETA</div><h2>{c[0]}</h2><div className="track-panel">{paths.length?<svg viewBox="0 0 360 200" role="img" aria-label="OSM 주변 레이스웨이">{paths.map((d,i)=><path key={i} d={d} fill="none" stroke="var(--accent)" strokeWidth="2.5" strokeLinejoin="round"/>)}</svg>:<div className="track-placeholder">TRACK DATA<small>공개 지도에서 주변 경로를 불러올 수 있습니다.</small></div>}</div><button disabled={busy} onClick={load}>{busy?'조회 중…':'OSM 경로 불러오기'}</button><small role="status">{status}</small><small className="attribution"><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors · ODbL</a> · 외부 지도 API 사용</small></section>}
const lessons=[['제동 압력','직선에서 충분히 감속하고 조향량이 늘수록 LT를 풀어준다.','코너 진입에서 브레이크를 갑자기 놓거나 강한 제동과 큰 조향을 동시에 하지 않는다.','M20 100 L45 20 H95 Q145 25 210 100 H340','M20 100 H190 Q245 100 310 20 H340'],['가속 압력','조향을 풀며 RT를 조금씩 증가시킨다.','차량이 아직 회전 중일 때 풀 스로틀을 피한다.','M20 100 H340','M20 100 H100 Q175 95 220 55 T340 20'],['조기 변속','저속 탈출에서 휠스핀이 발생하면 A로 한 단 일찍 올린다.','모든 직선에서 조기 변속할 필요는 없다.','M20 100 H340','M20 100 L105 45 L125 75 L205 35 L225 65 L340 20'],['관성 주행','평소 제동 지점보다 앞에서 RT를 놓고 이후 LT를 사용한다.','연료 절약보다 안전한 제동 지점 확보가 우선이다.','M20 100 H180 L200 25 H245 L280 100 H340','M20 20 H105 L120 100 H340'],['에너지 사용','추월 또는 방어가 필요한 직선에서 에너지를 사용한다.','배터리를 한 구간에서 모두 소진하지 않는다.','M20 100 H340','M20 100 H80 V25 H155 V100 H235 V25 H300 V100 H340']];
function Lesson({i,t,d}:{i:number,t:string,d:string}){const l=lessons[i];return <article className="lesson"><div className="eyebrow">TECHNIQUE / 0{i+1}</div><h3>{t}</h3><p>{d}</p><div className="telemetry"><div className="eyebrow">{l[0]} · INPUT CONCEPT</div><svg viewBox="0 0 360 135" role="img" aria-label={l[0]+' 개념 그래프'}>{[20,60,100].map(y=><line key={y} x1="20" x2="340" y1={y} y2={y} stroke="#35434d" strokeDasharray="4 4"/>)}<path d={l[3]} stroke="#ff7272" strokeWidth="3" fill="none"/><path d={l[4]} stroke="var(--accent)" strokeWidth="3" fill="none"/><text x="20" y="125" fill="#a0adb7" fontSize="10">START</text><text x="340" y="125" textAnchor="end" fill="#a0adb7" fontSize="10">END</text></svg><small>{i===2?'민트: RPM 변화 예시':i===4?'민트: 에너지 사용 예시':'빨강: 제동 · 민트: 가속'} · 실제 측정값 아님</small></div><p><b>연습</b> {l[1]}</p><p><b>주의</b> {l[2]}</p></article>}
'''
